# Load additional rich verified entries from local JSON banks
files1 = sorted(glob.glob("/working_dir/c_1510abc67ee9cabb/linguamaster-content/packs/vocabulary-reference/vocabulary/*.json"))
files2 = sorted(glob.glob("/working_dir/c_75864a886c894b07/linguamaster-content/packs/*/vocabulary/*.json"))

colloc_count = 0
for f in files1 + files2:
    try:
        d = json.load(open(f, encoding="utf-8"))
        entries = d if isinstance(d, list) else d.get("entries", d.get("items", []))
        for e in entries:
            hw = e.get("headword", e.get("word", "")).strip()
            ar = e.get("arabicMeaning", e.get("meaningAr", "")).strip()
            if not hw or not ar:
                continue
            pos = e.get("partOfSpeech", "noun").strip()
            cefr = e.get("cefrLevel", "B1").replace("Pre-A1", "A1").strip()
            dom = e.get("domain", "General").replace("_", " ").title()
            syns = ", ".join(e.get("synonyms", [])[:3]) if isinstance(e.get("synonyms"), list) else ""
            ants = ", ".join(e.get("antonyms", [])[:3]) if isinstance(e.get("antonyms"), list) else ""
            if " " not in hw:
                ADDITIONAL_DOMAIN_VOCAB.append((hw, ar, pos, dom, cefr, "", "", "", syns, ants))
            else:
                if colloc_count < 1200:
                    def_en = e.get("simpleEnglishDefinition", f"English collocation or phrase meaning '{ar}'.")
                    exs = e.get("examples", [])
                    ex_en = exs[0].get("en", "") if exs and isinstance(exs[0], dict) else ""
                    ex_ar = exs[0].get("ar", "") if exs and isinstance(exs[0], dict) else ""
                    IDIOMS_AND_PHRASES.append((hw, ar, ar, ar, def_en, ex_en, ex_ar, "Collocation"))
                    colloc_count += 1
                if colloc_count < 600:
                    ADDITIONAL_DOMAIN_VOCAB.append((hw, ar, "phrase", dom, cefr, "", "", "", syns, ants))
    except Exception:
        pass

# Extract rich parallel sentences from dialogues and vocabulary banks
EXTRA_PARALLEL_SENTENCES = []
try:
    d_diag = json.load(open("/working_dir/c_1510abc67ee9cabb/linguamaster-content/packs/dialogues/dialogues/dialogues-bank.json", encoding="utf-8"))
    for diag in d_diag.get("dialogues", []):
        for turn in diag.get("turns", []):
            en_s = re.sub(r'\([^)]*\)', '', turn.get("en", "")).strip() if 're' in globals() else turn.get("en", "").strip()
            ar_s = turn.get("ar", "").replace("(", "").replace(")", "").strip()
            if en_s and ar_s and len(en_s) > 15:
                EXTRA_PARALLEL_SENTENCES.append((en_s, ar_s, "Conversation"))
except Exception:
    pass

for f in files1[:4]:
    try:
        d = json.load(open(f, encoding="utf-8"))
        for e in d.get("entries", [])[:60]:
            exs = e.get("examples", [])
            if exs and isinstance(exs[0], dict):
                en_s = exs[0].get("en", "").strip()
                ar_s = exs[0].get("ar", "").replace("(", "").replace(")", "").strip()
                dom = e.get("domain", "General").replace("_", " ").title()
                if en_s and ar_s:
                    EXTRA_PARALLEL_SENTENCES.append((en_s, ar_s, dom))
    except Exception:
        pass

